/* @autogenerated */
package net.civeira.phylax.feature.observe.sourcemap;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.extern.slf4j.Slf4j;

/**
 * Source maps of the fronts, uploaded by their build ({@code POST /observe/api/sourcemaps}) and
 * kept per source and release in {@code <app.observe.path>/sourcemaps/}. The stacks of the errors
 * of a front are translated when they are shown (never when they arrive: the ingestion stays
 * light), with the maps of the release of the event. Only the last
 * {@code app.observe.sourcemaps.keep-releases} releases of each source are kept (the oldest uploads
 * are deleted).
 */
@ApplicationScoped
@Slf4j
public class SourceMaps {

  private static final long MAX_BYTES = 30L * 1024 * 1024;
  private static final Pattern SAFE = Pattern.compile("[^A-Za-z0-9._-]");
  /**
   * {@code at fn (https://host/main.4f2a.js:1:2345)}, {@code at https://...:1:2} or
   * {@code fn@url:1:2}.
   */
  private static final Pattern FRAME = Pattern.compile(
      "^(\\s*)(?:at\\s+(?:(.+?)\\s+\\()?|(.*?)@)(\\S+?/([^/?#]+\\.js))(?:[?#][^:]*)?:(\\d+):(\\d+)\\)?\\s*$");

  private final Path root;
  /** Releases of each source whose maps are kept (0: all). */
  @ConfigProperty(name = "app.observe.sourcemaps.keep-releases", defaultValue = "10")
  int keepReleases = 10;
  private final Map<String, Optional<SourceMap>> cache = new LinkedHashMap<>(16, 0.75f, true) {
    @Override
    protected boolean removeEldestEntry(final Map.Entry<String, Optional<SourceMap>> eldest) {
      return size() > 16;
    }
  };

  public SourceMaps(final @ConfigProperty(name = "app.observe.path",
      defaultValue = "data/observability") String path) {
    this.root = Path.of(path).resolve("sourcemaps");
  }

  /** Stores the map of a file of a release of a source (it replaces the previous one). */
  public void store(final String source, final String release, final String file,
      final String content) throws IOException {
    if (null == content || content.length() > MAX_BYTES) {
      throw new IllegalArgumentException("The source map is empty or too large");
    }
    SourceMap.parse(content);
    Path target = path(source, release, file);
    Files.createDirectories(target.getParent());
    Files.writeString(target, content, StandardCharsets.UTF_8);
    // The release is the newest one even when its maps are replaced
    Files.setLastModifiedTime(target.getParent(),
        java.nio.file.attribute.FileTime.fromMillis(System.currentTimeMillis()));
    synchronized (cache) {
      cache.remove(target.toString());
    }
    prune(target.getParent().getParent(), target.getParent());
  }

  /** Deletes the oldest releases of a source beyond keep-releases (never the one just uploaded). */
  private void prune(final Path sourceDir, final Path current) {
    if (keepReleases <= 0) {
      return;
    }
    try (java.util.stream.Stream<Path> releases = Files.list(sourceDir)) {
      java.util.List<Path> old =
          releases.filter(Files::isDirectory).filter(dir -> !dir.equals(current))
              .sorted(java.util.Comparator.comparingLong(SourceMaps::modified).reversed())
              .skip(Math.max(0, keepReleases - 1)).toList();
      for (Path dir : old) {
        try (java.util.stream.Stream<Path> files = Files.walk(dir)) {
          files.sorted(java.util.Comparator.reverseOrder()).forEach(path -> path.toFile().delete());
        }
        synchronized (cache) {
          cache.keySet().removeIf(key -> key.startsWith(dir.toString()));
        }
        log.info("Deleted the source maps of {}/{} (more than {} releases)",
            sourceDir.getFileName(), dir.getFileName(), keepReleases);
      }
    } catch (IOException ex) {
      log.warn("Unable to delete the old source maps of {}: {}", sourceDir, ex.getMessage());
    }
  }

  private static long modified(final Path dir) {
    try {
      return Files.getLastModifiedTime(dir).toMillis();
    } catch (IOException ex) {
      return 0;
    }
  }

  /**
   * The line of a stack translated to its original source, or empty if it is not a JavaScript frame
   * or there is no map for it.
   */
  public Optional<String> symbolicate(final String source, final String release,
      final String line) {
    if (null == source || null == release || null == line) {
      return Optional.empty();
    }
    Matcher matcher = FRAME.matcher(line);
    if (!matcher.matches()) {
      return Optional.empty();
    }
    String function = null != matcher.group(2) ? matcher.group(2) : matcher.group(3);
    Optional<SourceMap> map = map(path(source, release, matcher.group(5) + ".map"));
    return map
        .flatMap(
            m -> m.lookup(Integer.parseInt(matcher.group(6)), Integer.parseInt(matcher.group(7))))
        .map(position -> matcher.group(1) + "at "
            + (null != position.name() ? position.name()
                : null == function || function.isBlank() ? "<anonymous>" : function)
            + " (" + position.source() + ":" + position.line() + ":" + position.column() + ")");
  }

  private Optional<SourceMap> map(final Path file) {
    synchronized (cache) {
      return cache.computeIfAbsent(file.toString(), key -> {
        try {
          return Files.isRegularFile(file) ? Optional.of(SourceMap.parse(Files.readString(file)))
              : Optional.empty();
        } catch (IOException | RuntimeException ex) {
          log.warn("Unreadable source map {}: {}", file, ex.getMessage());
          return Optional.empty();
        }
      });
    }
  }

  private Path path(final String source, final String release, final String file) {
    String name = safe(file);
    return root.resolve(safe(source)).resolve(safe(release))
        .resolve(name.endsWith(".map") ? name : name + ".map");
  }

  /**
   * A name without path separators nor odd characters (the upload cannot write outside its folder).
   */
  static String safe(final String value) {
    String name = null == value ? "" : value.substring(value.lastIndexOf('/') + 1);
    name = SAFE.matcher(name).replaceAll("_");
    if (name.isEmpty() || name.chars().allMatch(c -> c == '.')) {
      throw new IllegalArgumentException("Invalid name " + value);
    }
    return name;
  }
}
